#!/usr/bin/env python3
# Accueil : illustrations editoriales et texte valides par Louis
# Dessins originaux, echanges a trois et suppression de la reference a la France.
from pathlib import Path
import hashlib, json, base64
ENTRIES = json.loads('[{"path": "assets/home/editorial.css", "old_sha256": null, "new_sha256": "9e81852e98f83f94d054f3da85d47736abf57ba6bbaf2dd8b8886503a55f5d45", "data": ""}, {"path": "assets/home/editorial/conversation.webp", "old_sha256": null, "new_sha256": "3277be009637b3a4e730aeee07d35bb5de33929aed0edd02285eb44bb25515f7", "data": ""}, {"path": "assets/home/editorial/pairs-v2.webp", "old_sha256": null, "new_sha256": "9da19a94f7e0c720eef75c42b0374eb2fc1b192fc3ba38f7399de59cf5be8b41", "data": ""}, {"path": "assets/home/editorial/patrimoine.webp", "old_sha256": null, "new_sha256": "34c8ec05b5d66ff19a9de5cb36492612d7fcb3c25686624058e8e49e913aacad", "data": ""}, {"path": "assets/home/editorial/temps.webp", "old_sha256": null, "new_sha256": "75bb1482119a53961e519cc4e360a0a0b351eb64860ddd63a1628f8edb4d14a2", "data": ""}, {"path": "index.html", "old_sha256": "d4892f36d34e55a69d3d1ee3f97bfc3404e34044b17a6d921677d7d1df725d5c", "new_sha256": "96575ebb7847e444572f5aeb89fb91daafb5570b28b98ddfc103ef3cb2276d69", "data": ""}]')
root = Path.cwd().resolve()
prepared = []
for entry in ENTRIES:
    path = (root / entry['path']).resolve()
    assert path.is_relative_to(root), entry['path']
    current = hashlib.sha256(path.read_bytes()).hexdigest() if path.exists() else None
    assert current == entry['old_sha256'], 'Concurrent change: ' + entry['path']
    data = base64.b64decode(entry['data'], validate=True)
    assert hashlib.sha256(data).hexdigest() == entry['new_sha256']
    prepared.append((path, data))
for path, data in prepared:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(data)
print('Six approved homepage files applied; directory untouched.')
